# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class ExplorerM2mTrackTrip(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "explorer_m2m_track_trip"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the "
            "database using gen_random_uuid()."
        ),
    )
    slot_position: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        comment=(
            "Zero-based ordering position of this "
            "track within the parent trip. Determines "
            "the display and day sequence."
        ),
    )
    track_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_track.id", ondelete="CASCADE"),
        nullable=False,
        comment=(
            "FK to explorer_agg_track with CASCADE "
            "delete. The recorded GPS activity "
            "included in this trip."
        ),
    )
    trip_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_trip.id", ondelete="CASCADE"),
        nullable=False,
        comment=(
            "FK to explorer_agg_trip with CASCADE "
            "delete. The parent trip this track "
            "belongs to."
        ),
    )
    waypoint_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("explorer_sub_waypoint.id"),
        comment=(
            "FK to explorer_sub_waypoint. Optional "
            "waypoint associated with this track "
            "within the trip."
        ),
    )
    day_name: Mapped[str] = mapped_column(
        Text,
        nullable=False,
        comment=(
            "Human-readable label for this day in "
            "the trip, such as 'Day 1' or "
            "'Day 3: Summit Day'. Required."
        ),
    )
    day_summary: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Short summary of this day's activities within the trip."
        ),
    )
    day_description: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Detailed description of this day's "
            "activities, including highlights and "
            "logistics."
        ),
    )
